parameters.jsCode:
// The planner. Every hour it reads the leases, the bank tab and the log, and
// writes down what has happened and what should happen next: a rent that fell
// due, a payment matched, a fee, a reminder, a review. It sends nothing itself
// - every message it decides on is a row in the log first, so a text that
// failed is never sent twice and one that was sent is never forgotten.

const cfg = $('Set Rent Settings').first().json;
const txt = $('Set Message Texts').first().json;

function rowsOf(name) {
  try {
    const rows = $(name).first().json.rows || [];
    return rows.filter((r) => r && typeof r === 'object' && Object.keys(r).length);
  } catch (e) {
    return [];
  }
}

const HOUR = 3600000;
const DAY = 86400000;
// Always Date.now(), never new Date() with no argument: one clock, read once.
const NOW = Date.now();
const STAMP = new Date(NOW).toISOString();

const num = (v, d) => {
  if (v === null || v === undefined || String(v).trim() === '') return d;
  const n = Number(String(v).replace(',', '.'));
  return Number.isFinite(n) ? n : d;
};
const yes = (v) => v === true || /^(true|yes|y|1|si|sì)$/i.test(String(v == null ? '' : v).trim());
const low = (v) => String(v == null ? '' : v).trim().toLowerCase();
const placeholder = (v) => !String(v || '').trim() || /^YOUR_/.test(String(v).trim());
const pick = (...vals) => vals.find((v) => v !== undefined && v !== null && String(v).trim() !== '');
const words = (s) => ' ' + low(s).normalize('NFD').replace(/[̀-ͯ]/g, '')
  .replace(/[^a-z0-9]+/g, ' ').trim() + ' ';
const squash = (s) => words(s).trim();

// --- days, in the landlord's own time zone ------------------------------------
// Rent is due on a day, not at an instant. Days are 'YYYY-MM-DD' strings, and
// arithmetic on them is done in whole days counted from 1970, never in hours,
// so a change to summer time cannot move a due date.

const TZ = String(cfg.timezone || 'UTC');
const LOCALE = String(cfg.locale || 'en-GB');
const partsFmt = new Intl.DateTimeFormat('en-GB', {
  timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', hourCycle: 'h23',
});
function local(t) {
  const o = {};
  for (const p of partsFmt.formatToParts(new Date(t))) o[p.type] = p.value;
  return { date: `${o.year}-${o.month}-${o.day}`, hour: Number(o.hour) % 24 };
}
const pad = (n) => String(n).padStart(2, '0');
const dn = (s) => {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(s || ''));
  return m ? Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3])) / DAY : NaN;
};
const ds = (n) => new Date(n * DAY).toISOString().slice(0, 10);
const TODAY = local(NOW).date;
const T = dn(TODAY);
const daysIn = (ym) => new Date(Date.UTC(Number(ym.slice(0, 4)), Number(ym.slice(5, 7)), 0)).getUTCDate();
function addMonths(ym, k) {
  const total = Number(ym.slice(0, 4)) * 12 + Number(ym.slice(5, 7)) - 1 + k;
  return `${Math.floor(total / 12)}-${pad((total % 12) + 1)}`;
}
// The 31st in a 30-day month is the 30th. February the 29th, in a year
// without one, is the 28th.
const dayIn = (ym, day) => `${ym}-${pad(Math.min(Math.max(1, Math.round(day)), daysIn(ym)))}`;
const later = (a, b) => (a > b ? a : b);
const sooner = (a, b) => (a < b ? a : b);

function dateOnly(v) {
  if (v === null || v === undefined) return '';
  if (typeof v === 'number' && v > 20000 && v < 80000) return ds(Math.floor(v) - 25569);  // a Sheets serial
  const s = String(v).trim();
  let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  let out = '';
  if (m) out = `${m[1]}-${pad(m[2])}-${pad(m[3])}`;
  m = !out && s.match(/^(\d{1,2})[/.-](\d{1,2})[/.-](\d{2}|\d{4})\b/);
  if (m) {
    const [d, mo] = String(cfg.date_order) === 'MDY' ? [m[2], m[1]] : [m[1], m[2]];
    out = `${m[3].length === 2 ? `20${m[3]}` : m[3]}-${pad(mo)}-${pad(d)}`;
  }
  return out && ds(dn(out)) === out ? out : '';     // 31/02 is not a date
}
function monthOf(v) {
  const s = String(v == null ? '' : v).trim();
  const m = s.match(/^(\d{4})[-/](\d{1,2})$/) || s.match(/^(\d{1,2})[-/](\d{4})$/);
  if (m) return m[1].length === 4 ? `${m[1]}-${pad(m[2])}` : `${m[2]}-${pad(m[1])}`;
  const d = dateOnly(v);
  return d ? d.slice(0, 7) : '';
}

const dayFmt = new Intl.DateTimeFormat(LOCALE, { timeZone: 'UTC', day: 'numeric', month: 'long', year: 'numeric' });
const monthFmt = new Intl.DateTimeFormat(LOCALE, { timeZone: 'UTC', month: 'long', year: 'numeric' });
const dayLabel = (s) => (dn(s) === dn(s) ? dayFmt.format(new Date(dn(s) * DAY)) : String(s));
const monthLabel = (ym) => monthFmt.format(new Date(Date.UTC(Number(ym.slice(0, 4)), Number(ym.slice(5, 7)) - 1, 15)));

// --- money, in whole cents ------------------------------------------------------
// 0.1 + 0.2 is not 0.3 in JavaScript, and a balance that is 0.+1234567890 out is
// a tenant chased for nothing. Every amount is an integer number of cents.

function amountOf(v) {
  if (typeof v === 'number') return Number.isFinite(v) ? Math.round(v * 100) : NaN;
  const raw = String(v == null ? '' : v).trim();
  if (!raw) return NaN;
  const negative = /-/.test(raw) || /^\(.*\)$/.test(raw) || /\bdr\b/i.test(raw);
  const s = raw.replace(/[^\d.,]/g, '');
  if (!/\d/.test(s)) return NaN;
  // The last separator is the decimal one when there are two kinds. With one
  // kind, three digits after it is thousands - 1,250 or 1.250 - because rent
  // is never quoted to a tenth of a penny.
  const dot = s.lastIndexOf('.');
  const comma = s.lastIndexOf(',');
  let whole = s;
  let frac = '';
  if (dot >= 0 && comma >= 0) {
    const at = Math.max(dot, comma);
    whole = s.slice(0, at).replace(/[.,]/g, '');
    frac = s.slice(at + 1);
  } else if (dot >= 0 || comma >= 0) {
    const pieces = s.split(dot >= 0 ? '.' : ',');
    const tail = pieces[pieces.length - 1];
    if (pieces.length === 2 && tail.length >= 1 && tail.length <= 2) [whole, frac] = pieces;
    else whole = pieces.join('');
  }
  if (frac.length > 2) return NaN;
  const cents = Number(whole || '0') * 100 + Number((frac + '00').slice(0, 2));
  return negative ? -cents : cents;
}
const toCents = (v) => {
  const c = amountOf(v);
  return Number.isFinite(c) ? c : 0;
};
const fromCents = (c) => (c / 100).toFixed(2);
function money(c) {
  try {
    return new Intl.NumberFormat(LOCALE, { style: 'currency', currency: String(cfg.currency || 'EUR') }).format(c / 100);
  } catch (e) {
    return `${fromCents(c)} ${cfg.currency || ''}`.trim();
  }
}
const floor = toCents(cfg.chase_floor);
const grace = num(cfg.grace_days, 3);

// --- people -------------------------------------------------------------------

const normEmail = (s) => {
  const m = String(s || '').toLowerCase().match(/[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/);
  return m ? m[0] : '';
};
// Numbers become +<country><number>. The trunk 0 is dropped, as it is in
// London (07700 -> +1234567890), except in Italy, where it is part of the number.
function normPhone(s) {
  let p = String(s || '').replace(/^\s*(whatsapp|sms|tel):/i, '').replace(/[^\d+]/g, '');
  if (p.startsWith('00')) p = '+' + p.slice(2);
  if (p && !p.startsWith('+')) {
    const cc = String(cfg.default_country_code || '').replace(/\D/g, '');
    if (!cc) return '';
    if (cc !== '39') p = p.replace(/^0/, '');
    p = `+${cc}${p}`;
  }
  const digits = p.replace(/\D/g, '');
  return digits.length >= 8 && digits.length <= 15 ? p : '';
}
const list = (v) => String(v || '').split(/\s*(?:;|,|&|\/|\band\b|\be\b)\s*/i).map((s) => s.trim()).filter(Boolean);

const leases = rowsOf('Aggregate Leases').map((r) => {
  const start = dateOnly(r.start);
  const names = list(r.tenants || r.tenant);
  return {
    id: String(r.lease_id || '').trim(),
    unit: String(r.unit || r.lease_id || '').trim(),
    owner: String(r.owner || '').trim(),
    names,
    payers: list(r.payers),
    name: names[0] || '',
    first_name: (names[0] || '').split(/\s+/)[0] || '',
    email: normEmail(r.email),
    phone: normPhone(r.phone),
    channel: low(r.channel),
    rent: toCents(r.rent),
    rentFrom: dateOnly(r.rent_from) || start,
    dueDay: num(r.due_day, 1),
    start,
    end: dateOnly(r.end),
    reference: String(r.reference || '').trim(),
    lateFee: String(r.late_fee == null ? '' : r.late_fee).trim(),
    index: low(r.index),
    indexCap: String(r.index_cap == null ? '' : r.index_cap).trim(),
    chase: !/^(no|n|false|0|off)$/.test(low(r.chase)),
    holdUntil: dateOnly(r.hold_until),
    opening: toCents(r.opening_balance),
    openingDue: dateOnly(r.opening_due),
    deposit: toCents(r.deposit),
  };
}).filter((l) => l.id && l.rent > 0 && l.start);
const leaseById = {};
for (const l of leases) leaseById[low(l.id)] = l;

// Where a message to this tenant goes: their own choice first, then text,
// then email - and never down a channel they said STOP to.
const twilioReady = !placeholder(cfg.twilio_from);
function reach(l, opted, formal) {
  if (!l) return null;
  const smsOk = twilioReady && l.phone && !opted[`sms:${l.phone}`];
  const mailOk = l.email && !opted[`email:${l.email}`];
  if ((formal || l.channel === 'email') && mailOk) return { channel: 'email', to: l.email };
  if (smsOk) return { channel: 'sms', to: l.phone };
  if (mailOk) return { channel: 'email', to: l.email };
  return null;
}

const fill = (template, vars) => String(template || '')
  .replace(/\{(\w+)\}/g, (m, k) => (vars[k] === undefined || vars[k] === null ? m : String(vars[k])));
const baseVars = {
  business: cfg.business_name || '',
  manager_name: cfg.manager_name || '',
  payment_details: cfg.payment_details || '',
};

// --- the log, read back into state ------------------------------------------
// The Log tab is the only thing this workflow writes to, and it only ever
// appends. Charges, payments, chases, promises and reviews are rebuilt from
// it here, the same way on every run.

function buildState(rows) {
  const S = { started: '', charges: {}, chargeIds: new Set(), pays: {}, payments: [], bankDone: new Set(),
    reversed: new Set(), unmatched: {}, episodes: {}, promises: {}, holds: {}, reviews: {}, proposals: {},
    increases: {}, alerts: {}, digests: {}, reports: {}, statements: {}, headsUps: new Set(), opted: {} };
  for (const r of rows) {
    const ev = String(r.event || '');
    const lease = String(r.lease_id || '');
    const at = Date.parse(r.at) || 0;
    const amount = toCents(r.amount);
    const key = String(r.charge_id || '');
    switch (ev) {
      case 'started':
        S.started = S.started || dateOnly(r.due);
        break;
      case 'charge':
        if (!S.chargeIds.has(key)) {
          S.chargeIds.add(key);
          (S.charges[lease] = S.charges[lease] || []).push({ id: key, due: dateOnly(r.due), amount,
            kind: String(r.detail || 'rent') });
        }
        break;
      case 'payment': {
        const p = { lease, bank: String(r.bank_id || ''), date: dateOnly(r.bank_date), amount,
          method: String(r.detail || ''), at };
        S.payments.push(p);
        (S.pays[lease] = S.pays[lease] || []).push(p);
        S.bankDone.add(p.bank);
        const m = /^reverses:(.+)$/.exec(p.method);
        if (m) S.reversed.add(m[1]);
        break;
      }
      case 'ignored':
        S.bankDone.add(String(r.bank_id || ''));
        break;
      case 'unmatched':
        S.unmatched[String(r.bank_id || '')] = at;
        break;
      case 'chased': {
        const e = S.episodes[lease] = S.episodes[lease] || { open: false, step: 0, firstAt: 0, lastAt: 0, past: [] };
        if (!e.open) Object.assign(e, { open: true, step: 0, firstAt: at });
        e.step = Math.max(e.step, num(r.step, 0));
        e.lastAt = at;
        break;
      }
      case 'cleared': {
        const e = S.episodes[lease];
        if (e && e.open) {
          e.past.push([e.firstAt, at]);
          Object.assign(e, { open: false, step: 0 });
        }
        break;
      }
      case 'promise':
        S.promises[lease] = { id: String(r.log_id || ''), due: dateOnly(r.due), amount, at, state: 'open' };
        break;
      case 'promise_kept':
      case 'promise_broken':
        if (S.promises[lease] && S.promises[lease].id === String(r.detail || '')) {
          S.promises[lease].state = ev === 'promise_kept' ? 'kept' : 'broken';
        }
        break;
      case 'hold':
        (S.holds[lease] = S.holds[lease] || []).push({ until: dateOnly(r.due), why: String(r.detail || ''), at });
        break;
      case 'review_proposed':
        S.proposals[key] = { lease, review: key.split(':').pop(), rent: amount, detail: String(r.detail || ''), at };
        S.reviews[key] = ev;
        break;
      case 'review_sent':
        S.reviews[key] = ev;
        (S.increases[lease] = S.increases[lease] || []).push({ effective: dateOnly(r.due), rent: amount,
          old: toCents((String(r.detail || '').match(/^from ([\d.]+)/) || [])[1]), at, key });
        break;
      case 'review_skipped':
      case 'review_none':
        S.reviews[key] = ev;
        break;
      case 'heads_up':
        S.headsUps.add(key);
        break;
      case 'alert':
        S.alerts[String(r.detail || '')] = at;
        break;
      case 'digest_sent':
        S.digests[String(r.detail || '')] = at;
        break;
      case 'report_sent':
        S.reports[String(r.detail || '')] = at;
        break;
      case 'statement_sent':
        S.statements[String(r.detail || '')] = at;
        break;
      case 'opt_out':
        S.opted[`${r.channel}:${r.contact}`] = true;
        break;
      case 'opt_in':
        delete S.opted[`${r.channel}:${r.contact}`];
        break;
      default:
        break;
    }
  }
  return S;
}

// The rent in force on a day: the Leases tab, unless a review the log knows
// about took effect after the date that rent was written down.
function rentOn(S, l, day) {
  let rent = l.rent;
  let since = l.rentFrom;
  for (const inc of S.increases[l.id] || []) {
    if (inc.effective <= day && inc.effective > since) {
      rent = inc.rent;
      since = inc.effective;
    }
  }
  return rent;
}

// Who owes what. Payments go to the oldest rent first and to late fees last,
// so a tenant who pays the rent in full is never in rent arrears because of
// a fee. `upTo` leaves out payments made after that day.
function ledger(S, l, upTo) {
  const charges = (S.charges[l.id] || []).map((c) => ({ ...c, paid: 0, paidOn: '' }))
    .sort((a, b) => ((a.kind === 'fee') - (b.kind === 'fee')) || (dn(a.due) - dn(b.due))
      || (a.id < b.id ? -1 : 1));
  const pays = (S.pays[l.id] || []).filter((p) => upTo === undefined || dn(p.date) <= upTo)
    .slice().sort((a, b) => (dn(a.date) - dn(b.date)) || (b.amount - a.amount));
  let credit = 0;
  for (const p of pays) {
    if (p.amount >= 0) {
      // Money returned more than was ever applied is owed first.
      const cover = credit < 0 ? Math.min(p.amount, -credit) : 0;
      credit += cover;
      let left = p.amount - cover;
      for (const c of charges) {
        if (left <= 0) break;
        const owed = c.amount - c.paid;
        if (owed <= 0) continue;
        const take = Math.min(owed, left);
        c.paid += take;
        left -= take;
        if (c.paid === c.amount) c.paidOn = p.date;
      }
      credit += Math.max(left, 0);
    } else {
      // A returned payment takes back the most recent money first.
      let back = -p.amount;
      const fromCredit = Math.min(Math.max(credit, 0), back);
      credit -= fromCredit;
      back -= fromCredit;
      for (const c of charges.slice().reverse()) {
        if (!back) break;
        const take = Math.min(c.paid, back);
        if (!take) continue;
        c.paid -= take;
        c.paidOn = '';
        back -= take;
      }
      credit -= back;
    }
  }
  const open = charges.filter((c) => c.amount - c.paid > 0).sort((a, b) => dn(a.due) - dn(b.due));
  const balance = open.reduce((s, c) => s + c.amount - c.paid, 0) - credit;
  return { charges, open, balance, credit, oldest: open[0] || null };
}

function chargeLabel(c) {
  if (c.kind === 'fee') return `Late fee (${monthLabel(c.id.split(':').slice(-2, -1)[0] || c.due.slice(0, 7))})`;
  if (c.kind === 'opening') return 'Balance brought forward';
  return `Rent ${monthLabel(c.id.split(':').pop())}`;
}
function statement(L) {
  const lines = L.open.map((c) => `  ${chargeLabel(c)}, due ${dayLabel(c.due)}: ${money(c.amount - c.paid)}` +
    (c.paid ? ` (of ${money(c.amount)})` : ''));
  if (L.credit > 0) lines.push(`  Paid in advance: -${money(L.credit)}`);
  lines.push(`  Total outstanding: ${money(L.balance)}`);
  return lines.join('\n');
}

const out = [];
let seq = 0;
function emit(event, fields, msg) {
  const row = {
    log_id: `${NOW.toString(36)}-${++seq}`, at: STAMP, event,
    lease_id: '', charge_id: '', bank_id: '', bank_date: '', amount: '', due: '', step: '',
    contact: '', channel: '', detail: '',
    ...(fields || {}),
  };
  if (msg) {
    row.send_channel = msg.channel;
    row.send_to = msg.to;
    row.send_subject = msg.subject || '';
    row.send_text = msg.text;
  }
  out.push({ json: row });
  return row;
}
const toManager = (subject, text) => ({ channel: 'email', to: cfg.manager_email, subject, text });
function message(kind, contact, vars) {
  const subject = fill(txt[`${kind}_subject`] || txt.subject_default || '{business}', vars);
  return { channel: contact.channel, to: contact.to, subject, text: fill(txt[kind], vars) };
}

const S = buildState(rowsOf('Aggregate Log'));
const canSend = (() => {
  const h = local(NOW).hour;
  return h >= num(cfg.send_from_hour, 9) && h < num(cfg.send_to_hour, 19);
})();
const bal = (l) => ledger(S, l).balance;

// ---------------------------------------------------------------------------
// 1. The day this started. Nothing before it is charged, and no bank line
// before it is read: arrears from before go in the lease's opening balance.
// ---------------------------------------------------------------------------

const goLive = dateOnly(cfg.go_live_date) || S.started || TODAY;
if (!S.started && !dateOnly(cfg.go_live_date)) {
  emit('started', { due: TODAY });
  S.started = TODAY;
}

// ---------------------------------------------------------------------------
// 2. Rent that has fallen due
// ---------------------------------------------------------------------------

function addCharge(l, id, due, amount, kind) {
  if (S.chargeIds.has(id) || amount <= 0) return;
  S.chargeIds.add(id);
  (S.charges[l.id] = S.charges[l.id] || []).push({ id, due, amount, kind });
  emit('charge', { lease_id: l.id, charge_id: id, due, amount: fromCents(amount), detail: kind });
}

for (const l of leases) {
  // Arrears brought in keep their age: a tenant 60 days behind on the day
  // this starts is 60 days behind, not new.
  if (l.opening > 0) addCharge(l, `${l.id}:opening`, l.openingDue || later(goLive, l.start), l.opening, 'opening');
  if (l.opening < 0 && !S.bankDone.has(`opening:${l.id}`)) {
    const p = { lease: l.id, bank: `opening:${l.id}`, date: later(goLive, l.start), amount: -l.opening,
      method: 'opening credit', at: NOW };
    emit('payment', { lease_id: l.id, bank_id: p.bank, bank_date: p.date, amount: fromCents(p.amount),
      detail: p.method });
    S.payments.push(p);
    (S.pays[l.id] = S.pays[l.id] || []).push(p);
    S.bankDone.add(p.bank);
  }
  for (let ym = later(l.start, goLive).slice(0, 7); ym <= TODAY.slice(0, 7); ym = addMonths(ym, 1)) {
    const from = later(`${ym}-01`, l.start);
    const to = l.end ? sooner(dayIn(ym, 31), l.end) : dayIn(ym, 31);
    if (from > to) continue;
    const due = later(dayIn(ym, l.dueDay), l.start);
    if (due < goLive || due > TODAY) continue;
    // A month the tenant only lives in part of is charged for the days they do.
    const occupied = dn(to) - dn(from) + 1;
    const full = rentOn(S, l, due);
    const amount = occupied >= daysIn(ym) ? full : Math.round((full * occupied) / daysIn(ym));
    addCharge(l, `${l.id}:${ym}`, due, amount, 'rent');
  }
}

// ---------------------------------------------------------------------------
// 3. The bank tab: who paid
// ---------------------------------------------------------------------------
// A line is known by its transaction id if the bank gives one, otherwise by
// what it says, running balance included. So pasting the same statement
// twice adds nothing, and pasting a longer one adds only the new lines.
//
// Two lines that say exactly the same thing are one line pasted twice -
// unless somebody writes a lease_id on the second, which says it is a second
// payment. Counting it twice would mark a tenant paid with money we never
// got; counting it once at worst sends a reminder they can answer.

function hash(s) {
  let a = 0xdeadbeef;
  let b = 0x41c6ce57;
  for (let i = 0; i < s.length; i++) {
    const ch = s.charCodeAt(i);
    a = Math.imul(a ^ ch, 2654435761);
    b = Math.imul(b ^ ch, 1597334677);
  }
  a = Math.imul(a ^ (a >>> 16), 2246822507) ^ Math.imul(b ^ (b >>> 13), 3266489909);
  b = Math.imul(b ^ (b >>> 16), 2246822507) ^ Math.imul(a ^ (a >>> 13), 3266489909);
  return (b >>> 0).toString(36) + (a >>> 0).toString(36);
}

const copies = {};
const bankLines = rowsOf('Aggregate Bank').map((r) => {
  const date = dateOnly(pick(r.date, r.booking_date, r.value_date, r.transaction_date));
  const paidIn = pick(r.credit, r.paid_in, r.money_in);
  const paidOut = pick(r.debit, r.paid_out, r.money_out);
  const amount = paidIn !== undefined || paidOut !== undefined
    ? Math.abs(toCents(paidIn)) - Math.abs(toCents(paidOut))
    : toCents(r.amount);
  const ref = String(pick(r.reference, r.description, r.details, r.memo, r.narrative) || '');
  const payer = String(pick(r.payer, r.name, r.counterparty, r.from) || '');
  const tx = String(pick(r.transaction_id, r.id) || '').trim();
  const running = String(pick(r.balance, r.running_balance) || '').trim();
  const base = tx ? `tx:${tx}` : `b${hash(`${date}|${amount}|${squash(ref)}|${squash(payer)}|${running}`)}`;
  copies[base] = (copies[base] || 0) + 1;
  const lease = String(r.lease_id == null ? '' : r.lease_id).trim();
  return { id: copies[base] > 1 ? `${base}-${copies[base]}` : base, date, amount, ref, payer,
    text: `${payer} ${ref}`, lease, copy: copies[base] > 1 && !lease };
}).filter((b) => b.date && b.amount);
const pastedTwice = bankLines.filter((b) => b.copy && b.date >= goLive);
const bankById = {};
for (const b of bankLines) bankById[b.id] = b;

// Lateness is measured to the last day the bank tab covers. A statement
// pasted on Thursday that ends on Monday says nothing about Tuesday.
const bankThrough = bankLines.reduce((m, b) => later(m, b.date), '');
const asOf = bankThrough ? Math.min(dn(bankThrough), T) : -Infinity;

function pay(l, b, amount, method) {
  const p = { lease: l.id, bank: b.id, date: b.date, amount, method, at: NOW };
  emit('payment', { lease_id: l.id, bank_id: b.id, bank_date: b.date, amount: fromCents(amount),
    contact: b.payer.slice(0, 80), detail: method });
  S.payments.push(p);
  (S.pays[l.id] = S.pays[l.id] || []).push(p);
  S.bankDone.add(b.id);
}
const suspense = [];
function suspend(b, why, candidates) {
  if (!S.unmatched[b.id]) {
    emit('unmatched', { bank_id: b.id, bank_date: b.date, amount: fromCents(b.amount),
      contact: b.payer.slice(0, 80), detail: why });
    S.unmatched[b.id] = NOW;
  }
  suspense.push({ b, why, candidates });
}

// A reference matches as a whole word, separators optional: "L-104" is in
// "RENT L104 MAY" and in "l 104", but not in "L1045".
function refHit(ref, text) {
  const chars = squash(ref).replace(/ /g, '');
  if (chars.length < 3) return false;
  const re = new RegExp(`(^|[^a-z0-9])${chars.split('').join('[^a-z0-9]*')}(?![a-z0-9])`);
  return re.test(squash(text));
}
const TITLES = new Set(['mr', 'mrs', 'ms', 'miss', 'dr', 'sig', 'sigra', 'dott']);
// "ROSSI M", "M ROSSI", "MARIO ROSSI" are all Mario Rossi. "ROSSI" alone is
// not, and neither is "MARIA ROSSA".
function nameHit(name, text) {
  const n = squash(name).split(' ').filter((t) => t && !TITLES.has(t));
  const p = new Set(squash(text).split(' '));
  if (!n.length) return false;
  if (n.length === 1) return n[0].length >= 4 && p.has(n[0]);
  const first = n[0];
  const last = n[n.length - 1];
  return last.length >= 2 && p.has(last) && (p.has(first) || p.has(first[0]));
}
const payerHit = (l, text) => l.names.concat(l.payers).some((n) => nameHit(n, text));
const DEPOSIT = /\b(deposit|bond|cauzione|deposito cauzionale|security)\b/i;

function matchCredit(b) {
  // A person wrote the lease in the Bank tab: that is the answer.
  if (b.lease) {
    if (/^(-|ignore|skip|not rent|no|none)$/i.test(b.lease)) {
      emit('ignored', { bank_id: b.id, bank_date: b.date, amount: fromCents(b.amount), detail: 'marked not rent' });
      S.bankDone.add(b.id);
      return;
    }
    const ls = b.lease.split(/[;,+\s]+/).filter(Boolean).map((id) => leaseById[low(id)]);
    if (!ls.length || ls.some((l) => !l)) return suspend(b, `the lease_id written, "${b.lease}", is not in Leases`, []);
    if (ls.length === 1) return pay(ls[0], b, b.amount, 'assigned');
    return split(ls, b, 'assigned');
  }
  if (DEPOSIT.test(b.text)) return suspend(b, 'it looks like a deposit, not rent', leases.filter((l) => payerHit(l, b.text)));

  const byRef = leases.filter((l) => [l.reference, l.id].some((r) => r && refHit(r, b.text)));
  const byName = leases.filter((l) => payerHit(l, b.text));
  if (byRef.length === 1) return pay(byRef[0], b, b.amount, 'reference');
  let found = byRef;
  let method = 'reference';
  if (byRef.length > 1) {
    const both = byRef.filter((l) => byName.includes(l));
    if (both.length === 1) return pay(both[0], b, b.amount, 'reference and payer');
  } else if (byName.length) {
    if (byName.length === 1) return pay(byName[0], b, b.amount, 'payer');
    found = byName;
    method = 'payer';
  }
  if (found.length > 1) {
    // Two leases could own it. The amount may say which; if it does not,
    // a person does.
    // What a lease owes says more than what its rent is: of two Smiths on
    // 800 a month, the one who owes 800 is the one paying it.
    const owes = found.filter((l) => bal(l) === b.amount);
    if (owes.length === 1) return pay(owes[0], b, b.amount, `${method} and amount`);
    const owing = found.filter((l) => bal(l) > 0);
    const rent = (owes.length ? owes : owing).filter((l) => rentOn(S, l, b.date) === b.amount);
    if (!owes.length && rent.length === 1) return pay(rent[0], b, b.amount, `${method} and amount`);
    if (owing.length > 1 && owing.reduce((s, l) => s + bal(l), 0) === b.amount) return split(owing, b, `${method}, combined`);
    return suspend(b, `it could be ${found.map((l) => l.id).join(' or ')}`, found);
  }
  if (yes(cfg.match_by_amount)) {
    const exact = leases.filter((l) => bal(l) > 0 && bal(l) === b.amount);
    if (exact.length === 1) return pay(exact[0], b, b.amount, 'amount only');
    if (exact.length > 1) return suspend(b, `${exact.length} leases owe exactly this amount`, exact);
  }
  return suspend(b, 'no reference, payer or amount we recognise', []);
}

// One payment for several leases: each gets what it owes, the oldest lease
// first, and whatever is left goes to the last as credit.
function split(ls, b, method) {
  let left = b.amount;
  const owed = ls.map((l) => Math.max(bal(l), 0));
  ls.forEach((l, i) => {
    const take = i === ls.length - 1 ? left : Math.min(owed[i], left);
    if (take > 0) pay(l, b, take, method);
    left -= take;
  });
  S.bankDone.add(b.id);
}

// A direct debit that bounced, a transfer the payer's bank recalled. It
// reverses the payment it returns - found by amount, within three weeks, and
// by payer when there is more than one - or a person is told.
const REVERSAL = /\b(return(ed)?|reversal|reversed|unpaid|bounced?|chargeback|recall(ed)?|r[- ]?transaction|refer to payer|insufficient funds|storno|stornato|insoluto)\b/i;
const returned = [];
function matchReversal(b) {
  if (!REVERSAL.test(b.text)) return;
  const amount = -b.amount;
  const totals = {};
  for (const p of S.payments) {
    if (p.method.startsWith('reverses:') || S.reversed.has(p.bank)) continue;
    const gap = dn(b.date) - dn(p.date);
    if (gap < 0 || gap > 21) continue;
    totals[p.bank] = (totals[p.bank] || 0) + p.amount;
  }
  let ids = Object.keys(totals).filter((id) => totals[id] === amount);
  if (ids.length > 1) {
    const same = ids.filter((id) => bankById[id] && squash(bankById[id].payer)
      && squash(b.text).includes(squash(bankById[id].payer)));
    if (same.length) ids = same;
  }
  if (ids.length !== 1) {
    const key = `return-untraced:${b.id}`;
    if (!S.alerts[key]) emit('alert', { bank_id: b.id, bank_date: b.date, amount: fromCents(b.amount), detail: key });
    returned.push({ b, traced: false });
    return;
  }
  for (const p of S.payments.filter((x) => x.bank === ids[0] && !x.method.startsWith('reverses:'))) {
    const back = { lease: p.lease, bank: b.id, date: b.date, amount: -p.amount, method: `reverses:${ids[0]}`, at: NOW };
    emit('payment', { lease_id: p.lease, bank_id: b.id, bank_date: b.date, amount: fromCents(back.amount),
      detail: back.method });
    S.payments.push(back);
    (S.pays[p.lease] = S.pays[p.lease] || []).push(back);
    returned.push({ b, traced: true, lease: p.lease, amount: p.amount });
  }
  S.reversed.add(ids[0]);
  S.bankDone.add(b.id);
}

for (const b of bankLines.filter((x) => x.date >= goLive).sort((x, y) => dn(x.date) - dn(y.date))) {
  if (S.bankDone.has(b.id) || b.copy) continue;
  if (b.amount > 0) matchCredit(b);
  else matchReversal(b);
}

// ---------------------------------------------------------------------------
// 4. Late fees: once per month's rent, when the bank shows it unpaid
// ---------------------------------------------------------------------------

function holding(l, kinds) {
  return (S.holds[l.id] || []).find((h) => h.until >= TODAY && (!kinds || kinds.includes(h.why))) || null;
}
function feeRule(l) {
  const s = low(l.lateFee !== '' ? l.lateFee : cfg.late_fee);
  if (!s || s === 'none' || s === 'no') return null;
  if (s.endsWith('%')) {
    const pct = num(s.slice(0, -1), 0);
    return pct > 0 ? { pct } : null;
  }
  const flat = toCents(s);
  return flat > 0 ? { flat } : null;
}
const feeAfter = num(cfg.late_fee_after_days, 5);
for (const l of leases) {
  const rule = feeRule(l);
  if (!rule) continue;
  for (const c of (S.charges[l.id] || []).filter((x) => x.kind === 'rent')) {
    const id = `${c.id}:fee`;
    const th = dn(c.due) + feeAfter;
    // Only when the bank tab reaches that day, and only for a month that
    // has just gone late: switching fees on does not fine last spring.
    if (S.chargeIds.has(id) || asOf < th || T - th > 31) continue;
    if (holding(l, ['dispute', 'hardship'])) continue;
    const then = ledger(S, l, th).charges.find((x) => x.id === c.id);
    const unpaid = then ? then.amount - then.paid : 0;
    if (unpaid <= floor) continue;
    let fee = rule.pct ? Math.round((unpaid * rule.pct) / 100) : rule.flat;
    const cap = num(cfg.late_fee_cap_pct, 0);
    if (cap > 0) fee = Math.min(fee, Math.round((c.amount * cap) / 100));
    addCharge(l, id, ds(th), fee, 'fee');
  }
}

// ---------------------------------------------------------------------------
// 5. Promises kept and broken, and arrears that are over
// ---------------------------------------------------------------------------

const promiseGrace = num(cfg.promise_grace_days, 2);
const broken = new Set();
for (const l of leases) {
  const p = S.promises[l.id];
  if (!p || p.state !== 'open') continue;
  const since = local(p.at).date;
  const paid = (S.pays[l.id] || []).filter((x) => x.date >= since).reduce((s, x) => s + x.amount, 0);
  if (paid >= p.amount || bal(l) <= floor) {
    emit('promise_kept', { lease_id: l.id, amount: fromCents(paid), due: p.due, detail: p.id });
    p.state = 'kept';
  } else if (asOf > dn(p.due) + promiseGrace) {
    emit('promise_broken', { lease_id: l.id, amount: fromCents(paid), due: p.due, detail: p.id });
    p.state = 'broken';
    broken.add(l.id);
  }
}

for (const l of leases) {
  const e = S.episodes[l.id];
  if (e && e.open && bal(l) <= floor) {
    emit('cleared', { lease_id: l.id, step: String(e.step) });
    e.past.push([e.firstAt, NOW]);
    Object.assign(e, { open: false, step: 0 });
  }
}

// ---------------------------------------------------------------------------
// 6. The ladder: reminder, firm, formal, the manager
// ---------------------------------------------------------------------------
// One rung at a time, never two, and never sooner than min_gap_days after
// the last. Lateness counts from the oldest unpaid charge, to the last day
// the bank tab covers.

let ladder = String(cfg.ladder_days || '').split(/[,;\s]+/).filter(Boolean).map(Number);
if (ladder.length !== 4 || ladder.some((d) => !Number.isFinite(d))) ladder = [1, 7, 14, 21];
const STEPS = ['chase_1', 'chase_2', 'chase_3', 'escalate'];
const minGap = num(cfg.min_gap_days, 3) * DAY;

// A payment nobody has matched yet, close to what this tenant owes, may be
// theirs. Chasing somebody whose money is sitting in our own account is how
// a reminder becomes a complaint.
function unassignedFor(l, L) {
  return suspense.find(({ b }) => T - dn(b.date) <= 14
    && (b.amount === rentOn(S, l, TODAY) || (b.amount <= L.balance && b.amount * 2 >= L.balance))) || null;
}
function heldBecause(l, L) {
  if (!l.chase) return 'chasing is off for this lease';
  if (l.holdUntil && l.holdUntil >= TODAY) return `on hold until ${dayLabel(l.holdUntil)}`;
  const h = holding(l);
  if (h) return `${h.why.replace(/_/g, ' ')}, held until ${dayLabel(h.until)}`;
  const p = S.promises[l.id];
  if (p && p.state === 'open') return `promised ${money(p.amount)} by ${dayLabel(p.due)}`;
  const u = unassignedFor(l, L);
  if (u) return `an unassigned payment of ${money(u.b.amount)} on ${dayLabel(u.b.date)} may be theirs`;
  return '';
}

const held = [];
const calls = [];
const unreachable = [];
const overThreshold = [];
const legalMonths = num(cfg.legal_threshold_months, 2);

for (const l of leases) {
  const L = ledger(S, l);
  if (L.balance <= floor || !L.oldest) continue;
  const late = asOf - dn(L.oldest.due) - grace;
  const e = S.episodes[l.id] = S.episodes[l.id] || { open: false, step: 0, firstAt: 0, lastAt: 0, past: [] };

  // The threshold the landlord set for formal action: told once per arrears.
  const monthly = rentOn(S, l, TODAY);
  if (legalMonths > 0 && L.balance >= Math.round(monthly * legalMonths) && late >= 0) {
    const key = `threshold:${l.id}:${L.oldest.id}`;
    overThreshold.push(`- ${l.unit} (${l.name}): ${money(L.balance)}, ${(L.balance / monthly).toFixed(1)} months' rent`);
    if (!S.alerts[key]) {
      emit('alert', { lease_id: l.id, amount: fromCents(L.balance), detail: key }, toManager(
        `${cfg.business_name}: ${l.unit} owes ${legalMonths} months' rent`,
        `${l.name} at ${l.unit} owes ${money(L.balance)}, which is ${legalMonths} months' rent or more - ` +
        `the threshold you set for formal action.\n\n${statement(L)}\n\n` +
        `Nothing formal has been sent. That step is yours.`));
      S.alerts[key] = NOW;
    }
  }

  const next = (e.open ? e.step : 0) + 1;
  if (next > STEPS.length) continue;
  const escalate = broken.has(l.id);
  const reached = ladder.filter((d) => late >= d).length;
  if (!escalate && reached < next) continue;
  if (!escalate && e.open && NOW - e.lastAt < minGap) continue;
  const why = heldBecause(l, L);
  if (why) {
    held.push(`- ${l.unit} (${l.name}): ${money(L.balance)} - ${why}`);
    continue;
  }

  const kind = STEPS[next - 1];
  const days = Math.max(0, asOf - dn(L.oldest.due));
  const vars = { ...baseVars, first_name: l.first_name, name: l.name, unit: l.unit,
    balance: money(L.balance), oldest_due: dayLabel(L.oldest.due), days_late: days,
    statement: statement(L), reference: l.reference || l.id };
  const fields = { lease_id: l.id, charge_id: L.oldest.id, amount: fromCents(L.balance), step: String(next),
    detail: escalate ? `${kind}, promise broken` : kind };
  if (kind === 'escalate') {
    emit('chased', fields, toManager(
      `${cfg.business_name}: ${l.unit} - arrears for a person to handle`,
      `${l.name} at ${l.unit} owes ${money(L.balance)}, ${days} days after the oldest charge fell due. ` +
      `Three reminders have gone out${escalate ? ', and a promise to pay was broken' : ''}.\n\n${statement(L)}\n\n` +
      `Contact: ${[l.phone, l.email].filter(Boolean).join(', ') || 'none on file'}\n\n` +
      `The workflow sends nothing more to this tenant until the balance is cleared.`));
    calls.push(`- ${l.unit} (${l.name}): ${money(L.balance)} - all reminders sent, yours now`);
  } else if (!canSend) {
    continue;                                          // the next run inside sending hours sends it
  } else {
    const c = reach(l, S.opted, kind === 'chase_3');
    if (!c) {
      emit('chased', { ...fields, detail: `${kind}, no contact` });
      unreachable.push(`- ${l.unit} (${l.name}): ${money(L.balance)} - no phone or email we can use`);
    } else {
      emit('chased', { ...fields, contact: c.to, channel: c.channel }, message(kind, c, vars));
      if (kind === 'chase_3') calls.push(`- ${l.unit} (${l.name}): ${money(L.balance)} - formal reminder sent, please call ${l.phone || l.email}`);
    }
  }
  if (!e.open) Object.assign(e, { open: true, step: 0, firstAt: NOW });
  e.step = next;
  e.lastAt = NOW;
}

// ---------------------------------------------------------------------------
// 7. A word before the 1st, only to the ones who are usually late
// ---------------------------------------------------------------------------

const headsUpDays = num(cfg.heads_up_days, 3);
function usuallyLate(l) {
  const recent = ledger(S, l).charges.filter((c) => c.kind === 'rent' && dn(c.due) + grace < asOf)
    .sort((a, b) => dn(b.due) - dn(a.due)).slice(0, 6);
  return recent.filter((c) => !c.paidOn || dn(c.paidOn) > dn(c.due) + grace).length >= 2;
}
if (canSend && headsUpDays > 0) {
  for (const l of leases) {
    let ym = TODAY.slice(0, 7);
    if (dayIn(ym, l.dueDay) <= TODAY) ym = addMonths(ym, 1);
    const due = dayIn(ym, l.dueDay);
    const key = `${l.id}:${ym}`;
    if (dn(due) - T > headsUpDays || S.headsUps.has(key) || !l.chase) continue;
    if (due < l.start || (l.end && l.end < due)) continue;
    if (!usuallyLate(l)) continue;
    const c = reach(l, S.opted, false);
    if (!c) continue;
    const L = ledger(S, l);
    emit('heads_up', { lease_id: l.id, charge_id: key, due, contact: c.to, channel: c.channel },
      message('heads_up', c, { ...baseVars, first_name: l.first_name, name: l.name, unit: l.unit,
        rent: money(rentOn(S, l, due) + Math.max(L.balance, 0)), due_date: dayLabel(due),
        reference: l.reference || l.id }));
    S.headsUps.add(key);
  }
}

// ---------------------------------------------------------------------------
// 8. Rent reviews: worked out, approved, and noticed in time
// ---------------------------------------------------------------------------
// The index month is the one published by the review: two months before it
// by default, compared with the same month a year earlier. A notice sent
// late does not backdate the rise; it moves the date it takes effect.

const indexOf = {};
for (const r of rowsOf('Aggregate Index')) {
  const m = monthOf(pick(r.month, r.date));
  const v = num(r.value, NaN);
  if (m && Number.isFinite(v) && v > 0) indexOf[m] = v;
}
const notice = num(cfg.review_notice_days, 30);
const lead = num(cfg.review_lead_days, 14);
const pendingReviews = [];
const missingIndex = [];

function sendReview(l, key, review, rent, base, calc) {
  const effective = later(review, ds(T + notice));
  const c = reach(l, S.opted, true);
  const vars = { ...baseVars, first_name: l.first_name, name: l.name, unit: l.unit,
    index_name: cfg.index_name || 'the index', effective: dayLabel(effective), new_rent: money(rent),
    old_rent: money(base), calculation: calc };
  emit('review_sent', { lease_id: l.id, charge_id: key, due: effective, amount: fromCents(rent),
    contact: c ? c.to : '', channel: c ? c.channel : '',
    detail: `from ${fromCents(base)}; ${effective > review ? 'notice late, effective date moved; ' : ''}${calc}` },
  c ? message('review_notice', c, vars) : toManager(
    `${cfg.business_name}: rent review for ${l.unit} needs posting`,
    `There is no email or phone for ${l.name}. Please send this notice by post:\n\n${fill(txt.review_notice, vars)}`));
  (S.increases[l.id] = S.increases[l.id] || []).push({ effective, rent, old: base, at: NOW, key });
}

for (const l of leases) {
  const fixed = /^[\d.,]+\s*%?$/.test(l.index) ? num(l.index.replace('%', ''), NaN) : NaN;
  if (!l.index || l.index === 'none' || l.index === 'no') continue;
  for (let y = Number(l.start.slice(0, 4)) + 1; y <= Number(TODAY.slice(0, 4)) + 1; y++) {
    const ym = `${y}-${l.start.slice(5, 7)}`;
    const review = dayIn(ym, Number(l.start.slice(8, 10)));
    const key = `review:${l.id}:${review}`;
    // A rent written in the Leases tab on or after the review date is that
    // review, done by hand.
    if (review < goLive || (l.end && l.end <= review) || l.rentFrom >= review) continue;
    if (T < dn(review) - notice - lead) continue;
    if (S.reviews[key] === 'review_proposed') {
      const p = S.proposals[key];
      pendingReviews.push(`- ${l.unit}: ${money(p.rent)} from ${dayLabel(review)}` +
        (T > dn(review) - notice ? ' - LATE: each day now moves the date it takes effect' : '') +
        `  (reply APPROVE or SKIP to the email marked [RENT REVIEW ${l.id} ${review}])`);
      continue;
    }
    if (S.reviews[key]) continue;

    const base = rentOn(S, l, ds(dn(review) - 1));
    let pct;
    let calc;
    if (Number.isFinite(fixed)) {
      pct = fixed / 100;
      calc = `Fixed rise in the lease: ${fixed}%.`;
    } else {
      const ref = addMonths(ym, -num(cfg.index_lag_months, 2));
      const now = indexOf[ref];
      const then = indexOf[addMonths(ref, -12)];
      if (!now || !then) {
        const miss = [ref, addMonths(ref, -12)].filter((m) => !indexOf[m]);
        missingIndex.push(`- ${l.unit}: review on ${dayLabel(review)} needs ${miss.join(' and ')}`);
        const k = `index-missing:${miss.join(',')}`;
        if (!S.alerts[k]) {
          emit('alert', { lease_id: l.id, charge_id: key, detail: k });
          S.alerts[k] = NOW;
        }
        continue;
      }
      const share = num(cfg.index_share, 1);
      const change = now / then - 1;
      pct = change * share;
      calc = `${cfg.index_name || 'Index'} ${monthLabel(ref)}: ${now}, ${monthLabel(addMonths(ref, -12))}: ${then}. ` +
        `Change ${(change * 100).toFixed(2)}%` + (share !== 1 ? `, of which ${share * 100}% applies: ${(pct * 100).toFixed(2)}%.` : '.');
    }
    const cap = num(l.indexCap.replace('%', ''), num(String(cfg.index_cap_pct || '').replace('%', ''), NaN));
    if (Number.isFinite(cap) && pct * 100 > cap) {
      pct = cap / 100;
      calc += ` Capped at ${cap}%.`;
    }
    if (pct < 0 && !yes(cfg.allow_decrease)) {
      pct = 0;
      calc += ' The index fell; the rent stays the same.';
    }
    const rent = Math.round(base * (1 + pct));
    calc += ` ${money(base)} becomes ${money(rent)} a month.`;
    if (rent === base) {
      emit('review_none', { lease_id: l.id, charge_id: key, due: review, amount: fromCents(rent), detail: calc });
      S.reviews[key] = 'review_none';
    } else if (low(cfg.review_mode) === 'send') {
      sendReview(l, key, review, rent, base, calc);
      S.reviews[key] = 'review_sent';
    } else {
      emit('review_proposed', { lease_id: l.id, charge_id: key, due: review, amount: fromCents(rent), detail: calc },
        toManager(`${cfg.business_name}: rent review for ${l.unit} [RENT REVIEW ${l.id} ${review}]`,
          `${l.name}, ${l.unit}. Review date ${dayLabel(review)}.\n\n${calc}\n\n` +
          `Reply APPROVE to send the notice to the tenant, or SKIP to leave the rent as it is.

` +
          (T <= dn(review) - notice
            ? `Approve by ${dayLabel(ds(dn(review) - notice))} for it to start on ${dayLabel(review)}. `
            : `The ${notice} days' notice can no longer reach ${dayLabel(review)}. `) +
          `Approved later, it starts ${notice} days after you approve.`));
      S.reviews[key] = 'review_proposed';
      S.proposals[key] = { lease: l.id, review, rent, detail: calc, at: NOW };
    }
  }
}

// ---------------------------------------------------------------------------
// 9. The manager's list, once a day
// ---------------------------------------------------------------------------

const lastDigest = Math.max(0, ...Object.values(S.digests));
if (local(NOW).hour >= num(cfg.digest_hour, 9) && !S.digests[TODAY] && !placeholder(cfg.manager_email)) {
  const parts = [];
  if (leases.length && (!bankThrough || T - dn(bankThrough) > num(cfg.bank_stale_days, 4))) {
    parts.push(`The Bank tab ends on ${bankThrough ? dayLabel(bankThrough) : '(it is empty)'}. Nobody is ` +
      `counted late after that day until the latest statement is pasted in.`);
  }
  const byAmount = S.payments.filter((p) => p.method === 'amount only' && p.at > lastDigest);
  if (byAmount.length) {
    parts.push(`Matched by the amount alone - please check:\n` + byAmount.map((p) => {
      const b = bankById[p.bank] || {};
      return `- ${dayLabel(p.date)} ${money(p.amount)} "${(b.text || '').trim()}" -> ${p.lease}`;
    }).join('\n'));
  }
  if (suspense.length) {
    parts.push(`Payments nobody could match. Write the lease_id in the Bank tab's lease_id column ` +
      `(or "ignore" if it is not rent):\n` + suspense.map(({ b, why }) =>
      `- ${dayLabel(b.date)} ${money(b.amount)} "${b.text.trim()}" - ${why}`).join('\n'));
  }
  const bounced = returned.concat(S.payments.filter((p) => p.method.startsWith('reverses:') && p.at > lastDigest && p.at < NOW)
    .map((p) => ({ b: bankById[p.bank] || { date: p.date, amount: p.amount }, traced: true, lease: p.lease, amount: -p.amount })));
  if (bounced.length) {
    parts.push(`Returned payments:\n` + bounced.map((r) => r.traced
      ? `- ${dayLabel(r.b.date)} ${money(r.amount)} returned - taken back off ${r.lease}`
      : `- ${dayLabel(r.b.date)} ${money(-r.b.amount)} "${r.b.text.trim()}" - could not tell which payment it returns`).join('\n'));
  }
  if (pastedTwice.length) {
    parts.push(`Lines that appear twice in the Bank tab, counted once. If one is really a second ` +
      `payment, write the lease_id on the second copy:\n` + pastedTwice.map((b) =>
      `- ${dayLabel(b.date)} ${money(b.amount)} "${b.text.trim()}"`).join('\n'));
  }
  if (calls.length) parts.push(`To call:\n${calls.join('\n')}`);
  if (unreachable.length) parts.push(`No way to reach them:\n${unreachable.join('\n')}`);
  if (overThreshold.length) parts.push(`At or over ${legalMonths} months' rent:\n${overThreshold.join('\n')}`);
  if (held.length) parts.push(`Reminder due but held back:\n${held.join('\n')}`);
  if (pendingReviews.length) parts.push(`Rent reviews waiting for your answer:\n${pendingReviews.join('\n')}`);
  if (missingIndex.length) parts.push(`Add these months to the Index tab:\n${missingIndex.join('\n')}`);
  const ending = [];
  for (const l of leases) {
    if (!l.end) continue;
    const L = ledger(S, l);
    if (l.end >= TODAY && dn(l.end) - T <= num(cfg.expiry_alert_days, 90)) {
      ending.push(`- ${l.unit} (${l.name}): ends ${dayLabel(l.end)}`);
    } else if (l.end < TODAY && L.balance > floor) {
      ending.push(`- ${l.unit} (${l.name}): ended ${dayLabel(l.end)} owing ${money(L.balance)}` +
        (l.deposit ? `, deposit held ${money(l.deposit)}` : ''));
    }
  }
  if (ending.length) parts.push(`Leases ending or ended:\n${ending.join('\n')}`);
  if (parts.length) {
    emit('digest_sent', { detail: TODAY }, toManager(`${cfg.business_name}: rent today`, parts.join('\n\n')));
  }
}

// ---------------------------------------------------------------------------
// 10. The month: a statement for each owner, and what it was worth
// ---------------------------------------------------------------------------

const thisMonth = TODAY.slice(0, 7);
const month = addMonths(thisMonth, -1);
const inMonth = (d) => String(d || '').slice(0, 7) === month;
// Only months the workflow was running for: a first statement of zeros
// for the month before it started is noise, sent on the first day.
const statementDue = Number(TODAY.slice(8, 10)) >= num(cfg.statement_day, 5)
  && local(NOW).hour >= num(cfg.digest_hour, 9) && month >= goLive.slice(0, 7);

if (statementDue) {
  const owners = rowsOf('Aggregate Owners').map((o) => ({ name: String(o.owner || '').trim(),
    email: normEmail(o.email), fee: num(String(o.fee_pct == null ? '' : o.fee_pct).replace('%', ''), 0) }))
    .filter((o) => o.name && o.email);
  for (const o of owners) {
    const key = `${o.name}:${month}`;
    const mine = leases.filter((l) => low(l.owner) === low(o.name));
    if (S.statements[key] || !mine.length) continue;
    let charged = 0;
    let collected = 0;
    const lines = mine.map((l) => {
      const ch = (S.charges[l.id] || []).filter((c) => c.kind === 'rent' && inMonth(c.due)).reduce((s, c) => s + c.amount, 0);
      const got = (S.pays[l.id] || []).filter((p) => inMonth(p.date)).reduce((s, p) => s + p.amount, 0);
      charged += ch;
      collected += got;
      const owing = ledger(S, l).balance;
      return `  ${l.unit}: rent ${money(ch)}, received ${money(got)}${owing > floor ? `, owing ${money(owing)}` : ''}`;
    });
    const fee = Math.round((collected * o.fee) / 100);
    emit('statement_sent', { amount: fromCents(collected - fee), detail: key }, {
      channel: 'email', to: o.email,
      subject: `${cfg.business_name}: your statement for ${monthLabel(month)}`,
      text: `${monthLabel(month)}\n\n${lines.join('\n')}\n\n` +
        `Rent charged:        ${money(charged)}\n` +
        `Received:            ${money(collected)}\n` +
        `Management fee ${o.fee}%: -${money(fee)}\n` +
        `Due to you:          ${money(collected - fee)}`,
    });
  }

  if (!S.reports[month] && !placeholder(cfg.manager_email)) {
    let due = 0;
    let collected = 0;
    let recovered = 0;
    let onTime = 0;
    let rents = 0;
    let fees = 0;
    const aging = [0, 0, 0];
    let arrears = 0;
    for (const l of leases) {
      const L = ledger(S, l);
      for (const c of L.charges) {
        if (!inMonth(c.due)) continue;
        if (c.kind === 'fee') { fees += c.amount; continue; }
        if (c.kind === 'opening') continue;              // brought in, not due this month
        due += c.amount;
        if (c.kind === 'rent') {
          rents += 1;
          if (c.paidOn && dn(c.paidOn) <= dn(c.due) + grace) onTime += 1;
        }
      }
      const e = S.episodes[l.id];
      const spans = e ? e.past.concat(e.open ? [[e.firstAt, Infinity]] : []) : [];
      for (const p of (S.pays[l.id] || []).filter((x) => inMonth(x.date))) {
        collected += p.amount;
        // Recovered: paid while this lease was being chased.
        if (p.amount > 0 && spans.some(([a, b]) => p.date >= local(a).date && (b === Infinity || p.date <= local(b).date))) {
          recovered += p.amount;
        }
      }
      if (L.balance > floor && L.oldest) {
        arrears += L.balance;
        const age = asOf - dn(L.oldest.due);
        aging[age <= 30 ? 0 : age <= 60 ? 1 : 2] += L.balance;
      }
    }
    const rises = Object.values(S.increases).flat().filter((i) => inMonth(local(i.at).date) && i.old);
    const rise = rises.reduce((s, i) => s + (i.rent - i.old) * 12, 0);
    const lines = [
      `Recovered from arrears in ${monthLabel(month)}: ${money(recovered)}`,
      rises.length ? `Rent reviews sent: ${rises.length}, worth ${money(rise)} a year` : '',
      '',
      `Due:        ${money(due)}`,
      `Collected:  ${money(collected)}${due ? ` (${Math.round((collected / due) * 100)}%)` : ''}`,
      `On time:    ${onTime} of ${rents} rents`,
      `Late fees:  ${money(fees)} charged`,
      '',
      `Arrears today: ${money(arrears)}`,
      `  up to 30 days  ${money(aging[0])}`,
      `  31 to 60 days  ${money(aging[1])}`,
      `  over 60 days   ${money(aging[2])}`,
    ].filter((x, i) => x !== '' || i > 1);
    emit('report_sent', { amount: fromCents(recovered), detail: month }, toManager(
      `${cfg.business_name}: ${money(recovered)} recovered from arrears in ${monthLabel(month)}`,
      lines.join('\n')));
  }
}

return out;

// The rows are in the log. Now, and only now, the messages go.
return $('Plan the Day').all()
  .map((i) => i.json)
  .filter((r) => r.send_to && r.send_text)
  .map((r) => ({ json: { channel: r.send_channel, to: r.send_to, subject: r.send_subject, text: r.send_text } }));

// Who wrote, and whether a person did. Texts and emails arrive in two
// different shapes; from here on they are one.
//
// An out-of-office is not a reply, and the model is not asked whether it is
// one: RFC 3834 headers answer that, and they win. The quoted part of an email
// is cut off before anything reads it, because our own reminder is in there,
// and "Friday" in our text is not a promise in theirs.
//
// The manager's answer to a rent review is read here too, by the tag in its
// subject, and never by the model: a rent rise is not sent on a guess.

const cfg = $('Set Rent Settings').first().json;

function rows(name) {
  try { return ($(name).first().json.rows || []).filter((r) => r && Object.keys(r).length); } catch (e) { return []; }
}
function items(name) {
  try { return $(name).all(); } catch (e) { return []; }
}

const normEmail = (s) => {
  const m = String(s || '').toLowerCase().match(/[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/);
  return m ? m[0] : '';
};
function normPhone(s) {
  let p = String(s || '').replace(/^\s*(whatsapp|sms|tel):/i, '').replace(/[^\d+]/g, '');
  if (p.startsWith('00')) p = '+' + p.slice(2);
  if (p && !p.startsWith('+')) {
    const cc = String(cfg.default_country_code || '').replace(/\D/g, '');
    if (!cc) return '';
    if (cc !== '39') p = p.replace(/^0/, '');
    p = `+${cc}${p}`;
  }
  const digits = p.replace(/\D/g, '');
  return digits.length >= 8 && digits.length <= 15 ? p : '';
}

const known = new Set();
for (const r of rows('Aggregate Leases')) {
  if (normEmail(r.email)) known.add(normEmail(r.email));
  if (normPhone(r.phone)) known.add(normPhone(r.phone));
}
const manager = normEmail(cfg.manager_email);

function automatic(meta) {
  const raw = meta.headers || {};
  const pairs = Array.isArray(raw) ? raw.map((h) => [h.name, h.value]) : Object.entries(raw);
  const headers = {};
  for (const [name, value] of pairs) {
    headers[String(name).toLowerCase()] = String(value == null ? '' : value).trim().toLowerCase();
  }
  const submitted = headers['auto-submitted'] || '';
  if (submitted && submitted !== 'no') return true;
  if (headers['x-autoreply'] || headers['x-autorespond'] || headers['x-auto-response-suppress']) return true;
  if (['bulk', 'auto_reply', 'list', 'junk'].includes(headers.precedence || '')) return true;
  const subject = String(meta.subject || '').toLowerCase().replace(/^((re|fwd?|aw|sv|r|rif)\s*:\s*)+/g, '').trim();
  return /^(auto(matic)?[ -]?(reply|response|answer)|autoreply|out of (the )?office|ooo\b|absence|risposta automatica|undeliverable|delivery status notification)/.test(subject);
}

// What the person wrote above what they were replying to.
function fresh(text) {
  const out = [];
  for (const line of String(text || '').replace(/\r\n/g, '\n').split('\n')) {
    if (/^\s*>/.test(line)) break;
    if (/^\s*-{2,}\s*(original message|messaggio originale)/i.test(line)) break;
    if (/^\s*(on|il|el|le|am) .+(wrote|ha scritto|escribió|a écrit|schrieb):?\s*$/i.test(line)) break;
    if (/^\s*from:\s/i.test(line) && out.length) break;
    out.push(line);
  }
  return out.join('\n').trim().slice(0, 1500);
}

// Twilio's own opt-out words. Twilio has already stopped texting this number
// by the time we see the message, whatever we do.
const CARRIER_STOP = ['stop', 'stopall', 'unsubscribe', 'cancel', 'end', 'quit', 'revoke', 'optout'];
const CARRIER_START = ['start', 'unstop'];
function keyword(text, channel) {
  const w = String(text || '').trim().toLowerCase().replace(/[.!,;:\s]+$/g, '').replace(/^[\s"']+/, '');
  if (channel === 'sms' && CARRIER_STOP.includes(w)) return 'stop';
  if (channel === 'sms' && CARRIER_START.includes(w)) return 'opt_in';
  if (channel === 'email' && /^(stop|unsubscribe|disiscrivimi)$/.test(w)) return 'stop';
  if (/^(paid|sent|done|pagato|fatto)$/.test(w)) return 'paid';
  return '';
}

const pick = (...vals) => vals.find((v) => typeof v === 'string' && v.trim() !== '') || '';
const out = [];

for (const it of items('When a Text Arrives')) {
  const j = it.json || {};
  const inner = j.body && typeof j.body === 'object' ? j.body : {};
  const data = j.data && typeof j.data === 'object' ? j.data : {};
  const contact = normPhone(pick(j.From, inner.From, data.from, j.from));
  const text = pick(j.Body, inner.Body, data.body, typeof j.body === 'string' ? j.body : '').trim();
  if (!contact || !text || !known.has(contact)) continue;
  out.push({ json: { channel: 'sms', contact, text: text.slice(0, 1500), subject: '',
    keyword: keyword(text, 'sms'), review: '' } });
}

for (const it of items('When an Email Arrives')) {
  const j = it.json || {};
  const from = j.from && typeof j.from === 'object'
    ? (j.from.value && j.from.value[0] && j.from.value[0].address) || j.from.text : j.from;
  const contact = normEmail(from);
  if (!contact || automatic(j)) continue;
  const subject = String(j.subject || '');
  const text = fresh(j.text || j.textPlain || j.snippet || '');
  if (!text) continue;
  if (contact === manager) {
    const tag = subject.match(/\[RENT REVIEW (\S+) (\d{4}-\d{2}-\d{2})\]/);
    if (!tag) continue;                                 // the manager's own mail is not ours to read
    const first = text.trim().toLowerCase().split(/[\s.,!]+/)[0] || '';
    const decision = /^(approve|approved|yes|ok|okay|go)$/.test(first) ? 'approve'
      : /^(skip|no|reject|cancel)$/.test(first) ? 'skip' : '';
    out.push({ json: { channel: 'email', contact, text, subject, keyword: decision ? `review_${decision}` : 'review_unclear',
      review: `review:${tag[1]}:${tag[2]}` } });
    continue;
  }
  if (!known.has(contact)) continue;
  out.push({ json: { channel: 'email', contact, text, subject,
    keyword: keyword(text.split('\n')[0], 'email'), review: '' } });
}

return out;

// The reply, acted on. A tenant answering a reminder says one of a few
// things: it is paid, it will be paid on a day, the amount is wrong, they
// cannot pay. Each one changes what the planner does next, and none of them
// is taken from the model on trust:
//
//   the model has to quote the words it read the intent from, and a quote
//   that is not in the message is a guess - a guess goes to the manager;
//
//   a promised date has to be in the future, within max_promise_days, and on
//   the weekday the message names: "Friday" read as a Thursday is a person's
//   question, not a promise;
//
//   a promised amount counts only if the figure is in the message. Otherwise
//   the promise is for what they owe, and the answer says so, so the tenant
//   sees it and can say otherwise.

const cfg = $('Set Rent Settings').first().json;
const txt = $('Set Message Texts').first().json;

function rowsOf(name) {
  try {
    const rows = $(name).first().json.rows || [];
    return rows.filter((r) => r && typeof r === 'object' && Object.keys(r).length);
  } catch (e) {
    return [];
  }
}

const HOUR = 3600000;
const DAY = 86400000;
// Always Date.now(), never new Date() with no argument: one clock, read once.
const NOW = Date.now();
const STAMP = new Date(NOW).toISOString();

const num = (v, d) => {
  if (v === null || v === undefined || String(v).trim() === '') return d;
  const n = Number(String(v).replace(',', '.'));
  return Number.isFinite(n) ? n : d;
};
const yes = (v) => v === true || /^(true|yes|y|1|si|sì)$/i.test(String(v == null ? '' : v).trim());
const low = (v) => String(v == null ? '' : v).trim().toLowerCase();
const placeholder = (v) => !String(v || '').trim() || /^YOUR_/.test(String(v).trim());
const pick = (...vals) => vals.find((v) => v !== undefined && v !== null && String(v).trim() !== '');
const words = (s) => ' ' + low(s).normalize('NFD').replace(/[̀-ͯ]/g, '')
  .replace(/[^a-z0-9]+/g, ' ').trim() + ' ';
const squash = (s) => words(s).trim();

// --- days, in the landlord's own time zone ------------------------------------
// Rent is due on a day, not at an instant. Days are 'YYYY-MM-DD' strings, and
// arithmetic on them is done in whole days counted from 1970, never in hours,
// so a change to summer time cannot move a due date.

const TZ = String(cfg.timezone || 'UTC');
const LOCALE = String(cfg.locale || 'en-GB');
const partsFmt = new Intl.DateTimeFormat('en-GB', {
  timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', hourCycle: 'h23',
});
function local(t) {
  const o = {};
  for (const p of partsFmt.formatToParts(new Date(t))) o[p.type] = p.value;
  return { date: `${o.year}-${o.month}-${o.day}`, hour: Number(o.hour) % 24 };
}
const pad = (n) => String(n).padStart(2, '0');
const dn = (s) => {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(s || ''));
  return m ? Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3])) / DAY : NaN;
};
const ds = (n) => new Date(n * DAY).toISOString().slice(0, 10);
const TODAY = local(NOW).date;
const T = dn(TODAY);
const daysIn = (ym) => new Date(Date.UTC(Number(ym.slice(0, 4)), Number(ym.slice(5, 7)), 0)).getUTCDate();
function addMonths(ym, k) {
  const total = Number(ym.slice(0, 4)) * 12 + Number(ym.slice(5, 7)) - 1 + k;
  return `${Math.floor(total / 12)}-${pad((total % 12) + 1)}`;
}
// The 31st in a 30-day month is the 30th. February the 29th, in a year
// without one, is the 28th.
const dayIn = (ym, day) => `${ym}-${pad(Math.min(Math.max(1, Math.round(day)), daysIn(ym)))}`;
const later = (a, b) => (a > b ? a : b);
const sooner = (a, b) => (a < b ? a : b);

function dateOnly(v) {
  if (v === null || v === undefined) return '';
  if (typeof v === 'number' && v > 20000 && v < 80000) return ds(Math.floor(v) - 25569);  // a Sheets serial
  const s = String(v).trim();
  let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  let out = '';
  if (m) out = `${m[1]}-${pad(m[2])}-${pad(m[3])}`;
  m = !out && s.match(/^(\d{1,2})[/.-](\d{1,2})[/.-](\d{2}|\d{4})\b/);
  if (m) {
    const [d, mo] = String(cfg.date_order) === 'MDY' ? [m[2], m[1]] : [m[1], m[2]];
    out = `${m[3].length === 2 ? `20${m[3]}` : m[3]}-${pad(mo)}-${pad(d)}`;
  }
  return out && ds(dn(out)) === out ? out : '';     // 31/02 is not a date
}
function monthOf(v) {
  const s = String(v == null ? '' : v).trim();
  const m = s.match(/^(\d{4})[-/](\d{1,2})$/) || s.match(/^(\d{1,2})[-/](\d{4})$/);
  if (m) return m[1].length === 4 ? `${m[1]}-${pad(m[2])}` : `${m[2]}-${pad(m[1])}`;
  const d = dateOnly(v);
  return d ? d.slice(0, 7) : '';
}

const dayFmt = new Intl.DateTimeFormat(LOCALE, { timeZone: 'UTC', day: 'numeric', month: 'long', year: 'numeric' });
const monthFmt = new Intl.DateTimeFormat(LOCALE, { timeZone: 'UTC', month: 'long', year: 'numeric' });
const dayLabel = (s) => (dn(s) === dn(s) ? dayFmt.format(new Date(dn(s) * DAY)) : String(s));
const monthLabel = (ym) => monthFmt.format(new Date(Date.UTC(Number(ym.slice(0, 4)), Number(ym.slice(5, 7)) - 1, 15)));

// --- money, in whole cents ------------------------------------------------------
// 0.1 + 0.2 is not 0.3 in JavaScript, and a balance that is 0.+1234567890 out is
// a tenant chased for nothing. Every amount is an integer number of cents.

function amountOf(v) {
  if (typeof v === 'number') return Number.isFinite(v) ? Math.round(v * 100) : NaN;
  const raw = String(v == null ? '' : v).trim();
  if (!raw) return NaN;
  const negative = /-/.test(raw) || /^\(.*\)$/.test(raw) || /\bdr\b/i.test(raw);
  const s = raw.replace(/[^\d.,]/g, '');
  if (!/\d/.test(s)) return NaN;
  // The last separator is the decimal one when there are two kinds. With one
  // kind, three digits after it is thousands - 1,250 or 1.250 - because rent
  // is never quoted to a tenth of a penny.
  const dot = s.lastIndexOf('.');
  const comma = s.lastIndexOf(',');
  let whole = s;
  let frac = '';
  if (dot >= 0 && comma >= 0) {
    const at = Math.max(dot, comma);
    whole = s.slice(0, at).replace(/[.,]/g, '');
    frac = s.slice(at + 1);
  } else if (dot >= 0 || comma >= 0) {
    const pieces = s.split(dot >= 0 ? '.' : ',');
    const tail = pieces[pieces.length - 1];
    if (pieces.length === 2 && tail.length >= 1 && tail.length <= 2) [whole, frac] = pieces;
    else whole = pieces.join('');
  }
  if (frac.length > 2) return NaN;
  const cents = Number(whole || '0') * 100 + Number((frac + '00').slice(0, 2));
  return negative ? -cents : cents;
}
const toCents = (v) => {
  const c = amountOf(v);
  return Number.isFinite(c) ? c : 0;
};
const fromCents = (c) => (c / 100).toFixed(2);
function money(c) {
  try {
    return new Intl.NumberFormat(LOCALE, { style: 'currency', currency: String(cfg.currency || 'EUR') }).format(c / 100);
  } catch (e) {
    return `${fromCents(c)} ${cfg.currency || ''}`.trim();
  }
}
const floor = toCents(cfg.chase_floor);
const grace = num(cfg.grace_days, 3);

// --- people -------------------------------------------------------------------

const normEmail = (s) => {
  const m = String(s || '').toLowerCase().match(/[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/);
  return m ? m[0] : '';
};
// Numbers become +<country><number>. The trunk 0 is dropped, as it is in
// London (07700 -> +1234567890), except in Italy, where it is part of the number.
function normPhone(s) {
  let p = String(s || '').replace(/^\s*(whatsapp|sms|tel):/i, '').replace(/[^\d+]/g, '');
  if (p.startsWith('00')) p = '+' + p.slice(2);
  if (p && !p.startsWith('+')) {
    const cc = String(cfg.default_country_code || '').replace(/\D/g, '');
    if (!cc) return '';
    if (cc !== '39') p = p.replace(/^0/, '');
    p = `+${cc}${p}`;
  }
  const digits = p.replace(/\D/g, '');
  return digits.length >= 8 && digits.length <= 15 ? p : '';
}
const list = (v) => String(v || '').split(/\s*(?:;|,|&|\/|\band\b|\be\b)\s*/i).map((s) => s.trim()).filter(Boolean);

const leases = rowsOf('Aggregate Leases').map((r) => {
  const start = dateOnly(r.start);
  const names = list(r.tenants || r.tenant);
  return {
    id: String(r.lease_id || '').trim(),
    unit: String(r.unit || r.lease_id || '').trim(),
    owner: String(r.owner || '').trim(),
    names,
    payers: list(r.payers),
    name: names[0] || '',
    first_name: (names[0] || '').split(/\s+/)[0] || '',
    email: normEmail(r.email),
    phone: normPhone(r.phone),
    channel: low(r.channel),
    rent: toCents(r.rent),
    rentFrom: dateOnly(r.rent_from) || start,
    dueDay: num(r.due_day, 1),
    start,
    end: dateOnly(r.end),
    reference: String(r.reference || '').trim(),
    lateFee: String(r.late_fee == null ? '' : r.late_fee).trim(),
    index: low(r.index),
    indexCap: String(r.index_cap == null ? '' : r.index_cap).trim(),
    chase: !/^(no|n|false|0|off)$/.test(low(r.chase)),
    holdUntil: dateOnly(r.hold_until),
    opening: toCents(r.opening_balance),
    openingDue: dateOnly(r.opening_due),
    deposit: toCents(r.deposit),
  };
}).filter((l) => l.id && l.rent > 0 && l.start);
const leaseById = {};
for (const l of leases) leaseById[low(l.id)] = l;

// Where a message to this tenant goes: their own choice first, then text,
// then email - and never down a channel they said STOP to.
const twilioReady = !placeholder(cfg.twilio_from);
function reach(l, opted, formal) {
  if (!l) return null;
  const smsOk = twilioReady && l.phone && !opted[`sms:${l.phone}`];
  const mailOk = l.email && !opted[`email:${l.email}`];
  if ((formal || l.channel === 'email') && mailOk) return { channel: 'email', to: l.email };
  if (smsOk) return { channel: 'sms', to: l.phone };
  if (mailOk) return { channel: 'email', to: l.email };
  return null;
}

const fill = (template, vars) => String(template || '')
  .replace(/\{(\w+)\}/g, (m, k) => (vars[k] === undefined || vars[k] === null ? m : String(vars[k])));
const baseVars = {
  business: cfg.business_name || '',
  manager_name: cfg.manager_name || '',
  payment_details: cfg.payment_details || '',
};

// --- the log, read back into state ------------------------------------------
// The Log tab is the only thing this workflow writes to, and it only ever
// appends. Charges, payments, chases, promises and reviews are rebuilt from
// it here, the same way on every run.

function buildState(rows) {
  const S = { started: '', charges: {}, chargeIds: new Set(), pays: {}, payments: [], bankDone: new Set(),
    reversed: new Set(), unmatched: {}, episodes: {}, promises: {}, holds: {}, reviews: {}, proposals: {},
    increases: {}, alerts: {}, digests: {}, reports: {}, statements: {}, headsUps: new Set(), opted: {} };
  for (const r of rows) {
    const ev = String(r.event || '');
    const lease = String(r.lease_id || '');
    const at = Date.parse(r.at) || 0;
    const amount = toCents(r.amount);
    const key = String(r.charge_id || '');
    switch (ev) {
      case 'started':
        S.started = S.started || dateOnly(r.due);
        break;
      case 'charge':
        if (!S.chargeIds.has(key)) {
          S.chargeIds.add(key);
          (S.charges[lease] = S.charges[lease] || []).push({ id: key, due: dateOnly(r.due), amount,
            kind: String(r.detail || 'rent') });
        }
        break;
      case 'payment': {
        const p = { lease, bank: String(r.bank_id || ''), date: dateOnly(r.bank_date), amount,
          method: String(r.detail || ''), at };
        S.payments.push(p);
        (S.pays[lease] = S.pays[lease] || []).push(p);
        S.bankDone.add(p.bank);
        const m = /^reverses:(.+)$/.exec(p.method);
        if (m) S.reversed.add(m[1]);
        break;
      }
      case 'ignored':
        S.bankDone.add(String(r.bank_id || ''));
        break;
      case 'unmatched':
        S.unmatched[String(r.bank_id || '')] = at;
        break;
      case 'chased': {
        const e = S.episodes[lease] = S.episodes[lease] || { open: false, step: 0, firstAt: 0, lastAt: 0, past: [] };
        if (!e.open) Object.assign(e, { open: true, step: 0, firstAt: at });
        e.step = Math.max(e.step, num(r.step, 0));
        e.lastAt = at;
        break;
      }
      case 'cleared': {
        const e = S.episodes[lease];
        if (e && e.open) {
          e.past.push([e.firstAt, at]);
          Object.assign(e, { open: false, step: 0 });
        }
        break;
      }
      case 'promise':
        S.promises[lease] = { id: String(r.log_id || ''), due: dateOnly(r.due), amount, at, state: 'open' };
        break;
      case 'promise_kept':
      case 'promise_broken':
        if (S.promises[lease] && S.promises[lease].id === String(r.detail || '')) {
          S.promises[lease].state = ev === 'promise_kept' ? 'kept' : 'broken';
        }
        break;
      case 'hold':
        (S.holds[lease] = S.holds[lease] || []).push({ until: dateOnly(r.due), why: String(r.detail || ''), at });
        break;
      case 'review_proposed':
        S.proposals[key] = { lease, review: key.split(':').pop(), rent: amount, detail: String(r.detail || ''), at };
        S.reviews[key] = ev;
        break;
      case 'review_sent':
        S.reviews[key] = ev;
        (S.increases[lease] = S.increases[lease] || []).push({ effective: dateOnly(r.due), rent: amount,
          old: toCents((String(r.detail || '').match(/^from ([\d.]+)/) || [])[1]), at, key });
        break;
      case 'review_skipped':
      case 'review_none':
        S.reviews[key] = ev;
        break;
      case 'heads_up':
        S.headsUps.add(key);
        break;
      case 'alert':
        S.alerts[String(r.detail || '')] = at;
        break;
      case 'digest_sent':
        S.digests[String(r.detail || '')] = at;
        break;
      case 'report_sent':
        S.reports[String(r.detail || '')] = at;
        break;
      case 'statement_sent':
        S.statements[String(r.detail || '')] = at;
        break;
      case 'opt_out':
        S.opted[`${r.channel}:${r.contact}`] = true;
        break;
      case 'opt_in':
        delete S.opted[`${r.channel}:${r.contact}`];
        break;
      default:
        break;
    }
  }
  return S;
}

// The rent in force on a day: the Leases tab, unless a review the log knows
// about took effect after the date that rent was written down.
function rentOn(S, l, day) {
  let rent = l.rent;
  let since = l.rentFrom;
  for (const inc of S.increases[l.id] || []) {
    if (inc.effective <= day && inc.effective > since) {
      rent = inc.rent;
      since = inc.effective;
    }
  }
  return rent;
}

// Who owes what. Payments go to the oldest rent first and to late fees last,
// so a tenant who pays the rent in full is never in rent arrears because of
// a fee. `upTo` leaves out payments made after that day.
function ledger(S, l, upTo) {
  const charges = (S.charges[l.id] || []).map((c) => ({ ...c, paid: 0, paidOn: '' }))
    .sort((a, b) => ((a.kind === 'fee') - (b.kind === 'fee')) || (dn(a.due) - dn(b.due))
      || (a.id < b.id ? -1 : 1));
  const pays = (S.pays[l.id] || []).filter((p) => upTo === undefined || dn(p.date) <= upTo)
    .slice().sort((a, b) => (dn(a.date) - dn(b.date)) || (b.amount - a.amount));
  let credit = 0;
  for (const p of pays) {
    if (p.amount >= 0) {
      // Money returned more than was ever applied is owed first.
      const cover = credit < 0 ? Math.min(p.amount, -credit) : 0;
      credit += cover;
      let left = p.amount - cover;
      for (const c of charges) {
        if (left <= 0) break;
        const owed = c.amount - c.paid;
        if (owed <= 0) continue;
        const take = Math.min(owed, left);
        c.paid += take;
        left -= take;
        if (c.paid === c.amount) c.paidOn = p.date;
      }
      credit += Math.max(left, 0);
    } else {
      // A returned payment takes back the most recent money first.
      let back = -p.amount;
      const fromCredit = Math.min(Math.max(credit, 0), back);
      credit -= fromCredit;
      back -= fromCredit;
      for (const c of charges.slice().reverse()) {
        if (!back) break;
        const take = Math.min(c.paid, back);
        if (!take) continue;
        c.paid -= take;
        c.paidOn = '';
        back -= take;
      }
      credit -= back;
    }
  }
  const open = charges.filter((c) => c.amount - c.paid > 0).sort((a, b) => dn(a.due) - dn(b.due));
  const balance = open.reduce((s, c) => s + c.amount - c.paid, 0) - credit;
  return { charges, open, balance, credit, oldest: open[0] || null };
}

function chargeLabel(c) {
  if (c.kind === 'fee') return `Late fee (${monthLabel(c.id.split(':').slice(-2, -1)[0] || c.due.slice(0, 7))})`;
  if (c.kind === 'opening') return 'Balance brought forward';
  return `Rent ${monthLabel(c.id.split(':').pop())}`;
}
function statement(L) {
  const lines = L.open.map((c) => `  ${chargeLabel(c)}, due ${dayLabel(c.due)}: ${money(c.amount - c.paid)}` +
    (c.paid ? ` (of ${money(c.amount)})` : ''));
  if (L.credit > 0) lines.push(`  Paid in advance: -${money(L.credit)}`);
  lines.push(`  Total outstanding: ${money(L.balance)}`);
  return lines.join('\n');
}

const out = [];
let seq = 0;
function emit(event, fields, msg) {
  const row = {
    log_id: `${NOW.toString(36)}-${++seq}`, at: STAMP, event,
    lease_id: '', charge_id: '', bank_id: '', bank_date: '', amount: '', due: '', step: '',
    contact: '', channel: '', detail: '',
    ...(fields || {}),
  };
  if (msg) {
    row.send_channel = msg.channel;
    row.send_to = msg.to;
    row.send_subject = msg.subject || '';
    row.send_text = msg.text;
  }
  out.push({ json: row });
  return row;
}
const toManager = (subject, text) => ({ channel: 'email', to: cfg.manager_email, subject, text });
function message(kind, contact, vars) {
  const subject = fill(txt[`${kind}_subject`] || txt.subject_default || '{business}', vars);
  return { channel: contact.channel, to: contact.to, subject, text: fill(txt[kind], vars) };
}

const S = buildState(rowsOf('Aggregate Log'));
const replies = $('Read the Reply').all().map((i) => i.json);
const read = $input.all().map((i) => i.json || {});
const INTENTS = ['paid', 'promise', 'dispute', 'hardship', 'question', 'stop', 'other'];
const strip = (s) => low(s).replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
const notice = num(cfg.review_notice_days, 30);

function intentOf(r, ai) {
  if (r.keyword) return r.keyword;
  const got = (ai && (ai.output || ai)) || {};
  const intent = low(got.intent);
  if (!INTENTS.includes(intent)) return 'other';
  const evidence = strip(got.evidence);
  if (!evidence || !strip(r.text).includes(evidence)) return 'other';
  return intent;
}

const DAYS = { sunday: 0, monday: 1, tuesday: 2, wednesday: 3, thursday: 4, friday: 5, saturday: 6,
  domenica: 0, lunedi: 1, martedi: 2, mercoledi: 3, giovedi: 4, venerdi: 5, sabato: 6 };
const weekdaysIn = (text) => [...new Set(squash(text).split(' ').filter((w) => w in DAYS).map((w) => DAYS[w]))];
const WEEKDAY_NAMES = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
function amountsIn(text) {
  return (String(text || '').match(/\d[\d.,]*/g) || []).map(amountOf).filter((c) => Number.isFinite(c) && c > 0);
}

function promiseOf(r, ai, owed) {
  const got = (ai && (ai.output || ai)) || {};
  const date = dateOnly(got.promised_date);
  if (!date) return { error: 'they gave no date that could be read' };
  if (date < TODAY) return { error: `the date read, ${dayLabel(date)}, is in the past` };
  const max = num(cfg.max_promise_days, 31);
  if (dn(date) - T > max) return { error: `${dayLabel(date)} is more than ${max} days away` };
  const named = weekdaysIn(r.text);
  const wd = new Date(dn(date) * DAY).getUTCDay();
  if (named.length && !named.includes(wd)) {
    return { error: `the message names ${named.map((d) => WEEKDAY_NAMES[d]).join(' or ')}, but ` +
      `${dayLabel(date)} is a ${WEEKDAY_NAMES[wd]}` };
  }
  const said = amountOf(got.promised_amount);
  const inText = Number.isFinite(said) && said > 0 && amountsIn(r.text).includes(said);
  return { date, amount: inText ? said : owed, stated: inText };
}

function leasesOf(contact) {
  return leases.filter((l) => l.email === contact || l.phone === contact);
}
// An answer to an email stays in its conversation: "Re:" its own subject.
const replyTo = (r, kind, vars) => ({
  channel: r.channel, to: r.contact,
  subject: r.subject ? (/^re:/i.test(r.subject.trim()) ? r.subject.trim() : `Re: ${r.subject.trim()}`)
    : fill(txt[`${kind}_subject`] || txt.subject_default || '{business}', vars),
  text: fill(txt[kind], vars),
});
function forward(r, l, why) {
  const who = l ? `${l.name}, ${l.unit}` : r.contact;
  const L = l ? ledger(S, l) : null;
  emit('forwarded', { lease_id: l ? l.id : '', contact: r.contact, channel: r.channel, detail: why },
    toManager(`${cfg.business_name}: ${who} wrote`,
      `${why}\n\nFrom: ${who} (${r.contact}, by ${r.channel === 'sms' ? 'text' : 'email'})\n\n"${r.text}"` +
      (L ? `\n\nTheir account:\n${statement(L)}` : '')));
}
function hold(l, kind, days) {
  const until = ds(T + days);
  emit('hold', { lease_id: l.id, due: until, detail: kind });
  (S.holds[l.id] = S.holds[l.id] || []).push({ until, why: kind, at: NOW });
  return until;
}

replies.forEach((r, i) => {
  const intent = intentOf(r, read[i]);

  // --- the manager, about a rent review --------------------------------------
  if (r.review) {
    const p = S.proposals[r.review];
    const l = p && leaseById[low(p.lease)];
    if (!p || !l || S.reviews[r.review] !== 'review_proposed') return;
    if (intent === 'review_skip') {
      emit('review_skipped', { lease_id: l.id, charge_id: r.review, due: p.review, amount: fromCents(p.rent),
        contact: r.contact, detail: 'skipped by the manager' });
      S.reviews[r.review] = 'review_skipped';
      return;
    }
    if (intent !== 'review_approve') {
      emit('message', { lease_id: l.id, charge_id: r.review, contact: r.contact, detail: 'review reply unclear' },
        toManager(`${cfg.business_name}: rent review for ${l.unit} [RENT REVIEW ${l.id} ${p.review}]`,
          `Your reply did not start with APPROVE or SKIP, so nothing was sent. Reply again with one of the two.`));
      return;
    }
    const base = rentOn(S, l, ds(dn(p.review) - 1));
    const effective = later(p.review, ds(T + notice));
    const c = reach(l, S.opted, true);
    const vars = { ...baseVars, first_name: l.first_name, name: l.name, unit: l.unit,
      index_name: cfg.index_name || 'the index', effective: dayLabel(effective), new_rent: money(p.rent),
      old_rent: money(base), calculation: p.detail };
    emit('review_sent', { lease_id: l.id, charge_id: r.review, due: effective, amount: fromCents(p.rent),
      contact: c ? c.to : '', channel: c ? c.channel : '',
      detail: `from ${fromCents(base)}; ${effective > p.review ? 'notice late, effective date moved; ' : ''}${p.detail}` },
    c ? message('review_notice', c, vars) : toManager(
      `${cfg.business_name}: rent review for ${l.unit} needs posting`,
      `There is no email or phone for ${l.name}. Please send this notice by post:\n\n${fill(txt.review_notice, vars)}`));
    S.reviews[r.review] = 'review_sent';
    return;
  }

  const mine = leasesOf(r.contact);
  const owing = mine.filter((l) => ledger(S, l).balance > floor);
  const l = owing.length === 1 ? owing[0] : mine.length === 1 ? mine[0] : null;
  const vars = { ...baseVars, first_name: l ? l.first_name : '', unit: l ? l.unit : '' };

  if (intent === 'opt_in') {
    emit('opt_in', { contact: r.contact, channel: r.channel });
    delete S.opted[`${r.channel}:${r.contact}`];
    return;
  }
  if (intent === 'stop') {
    // Twilio answers STOP itself; an email STOP gets one line back. Rent is
    // still owed: reminders go by the other channel, or to the manager's list.
    emit('opt_out', { lease_id: l ? l.id : '', contact: r.contact, channel: r.channel },
      r.channel === 'email' ? replyTo(r, 'opted_out', vars) : null);
    S.opted[`${r.channel}:${r.contact}`] = true;
    return;
  }
  if (!l) {
    if (mine.length > 1) forward(r, null, `They rent ${mine.map((x) => x.unit).join(' and ')}; which one is this about?`);
    else if (r.channel === 'sms') forward(r, null, 'Not about a lease we could find.');
    return;
  }

  const L = ledger(S, l);
  const balance = Math.max(L.balance, 0);
  const fields = { lease_id: l.id, contact: r.contact, channel: r.channel };

  if (intent === 'paid') {
    // Believed for a few days, then the bank decides.
    const until = hold(l, 'says_paid', num(cfg.claim_hold_days, 3));
    emit('message', { ...fields, detail: 'says paid' }, replyTo(r, 'paid_ack', { ...vars, date: dayLabel(until) }));
    return;
  }
  if (intent === 'promise') {
    const p = promiseOf(r, read[i], balance);
    if (p.error) return forward(r, l, `They seem to promise a payment, but ${p.error}. Nothing was changed.`);
    emit('promise', { ...fields, due: p.date, amount: fromCents(p.amount), detail: p.stated ? 'amount stated' : 'full balance' },
      replyTo(r, 'promise_ack', { ...vars, amount: money(p.amount), date: dayLabel(p.date) }));
    return;
  }
  if (intent === 'dispute') {
    hold(l, 'dispute', num(cfg.dispute_hold_days, 14));
    emit('message', { ...fields, detail: 'dispute' }, replyTo(r, 'dispute_ack', vars));
    return forward(r, l, `They dispute what they owe. Reminders and late fees are paused for ` +
      `${num(cfg.dispute_hold_days, 14)} days; set hold_until in Leases to pause longer.`);
  }
  if (intent === 'hardship') {
    hold(l, 'hardship', num(cfg.dispute_hold_days, 14));
    emit('message', { ...fields, detail: 'hardship' }, replyTo(r, 'hardship_ack', vars));
    return forward(r, l, 'They say they cannot pay. Reminders and late fees are paused; they are expecting your call.');
  }
  return forward(r, l, intent === 'question' ? 'They asked a question.' : 'A reply the workflow could not act on.');
});

return out;

// After the log: the answers, and what goes to the manager.
return $('Apply the Reply').all()
  .map((i) => i.json)
  .filter((r) => r.send_to && r.send_text)
  .map((r) => ({ json: { channel: r.send_channel, to: r.send_to, subject: r.send_subject, text: r.send_text } }));

parameters.message:
=A run of the rent workflow stopped with an error.

Error:     {{ $json.execution.error.message }}
At node:   {{ $json.execution.lastNodeExecuted }}
Execution: {{ $json.execution.url }}

Decisions are logged before messages are sent, so the next run sends nothing twice and charges nobody twice.
